import { Block, Text } from "@prototyp/skeletor";
import { type FC, useEffect, useRef } from "react";
import { Animated, Image, StyleSheet } from "react-native";
import { Button } from "shared/components";

interface Props {
  visible: boolean;
  onPress: () => void;
}

export const NewMessagesButton: FC<Props> = ({ visible, onPress }) => {
  const animValue = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    Animated.spring(animValue, {
      toValue: visible ? 1 : 0,
      useNativeDriver: true,
      bounciness: 8,
    }).start();
  }, [visible, animValue]);

  const translateY = animValue.interpolate({
    inputRange: [0, 1],
    outputRange: [16, 0],
  });

  return (
    <Block
      absolute
      offsets={{ right: 0, bottom: 100 }}
      align="center"
      justify="center"
      width="100%"
      pointerEvents={visible ? "auto" : "none"}
    >
      <Animated.View style={{ opacity: animValue, transform: [{ translateY }] }}>
        <Button.Outline size="medium" onPress={onPress}>
          <Text>New messages</Text>
          <Image source={require("assets/icons/arrow-down.png")} />
        </Button.Outline>
      </Animated.View>
    </Block>
  );
};

const styles = StyleSheet.create({});

